            (1, 'Which schools were studied?', 'Schools near busy roads and airports', ['Schools in forests', 'Schools in the mountains only', 'Schools abroad only']),
            (2, 'According to the passage, silence is …', 'not simply the absence of noise', ['always boring', 'harmful to health', 'impossible in schools']),
            (2, 'What effect does two minutes of quiet at the start of the day have?', 'Classes settle faster and pupils seem calmer.', None),
            (3, 'How can planting trees reduce noise?', 'Leaves and branches absorb some sound.', None),
            (3, 'Which of these is suggested for drivers?', 'Avoiding needless honking', ['Driving faster', 'Using louder horns', 'Playing music loudly']),
            (4, 'What question does the writer want each of us to ask?', '"Is this sound necessary?"', None),
            (3, 'Which word in paragraph 4 means "take in or soak up"?', 'absorb', ['avoid', 'follow', 'lower']),
            (4, 'The writer\'s attitude to a quieter world is …', 'hopeful', ['hopeless', 'indifferent', 'angry']),
